import React from 'react';
import { Bot } from 'lucide-react';

export type ProviderType =
  | 'hermes'
  | 'antigravity'
  | 'claude'
  | 'codex'
  | 'deepseek'
  | 'kimi'
  | 'ollama'
  | 'gemini'
  | 'copilot'
  | 'cursor'
  | 'mistral'
  | 'qwen'
  | 'llama'
  | 'none'
  | 'generic';

export function detectProviderType(
  harness?: string,
  agentName?: string,
  command?: string
): ProviderType {
  if (harness === 'none' || harness === 'terminal' || agentName === 'Terminal') {
    return 'none';
  }

  const str = `${harness || ''} ${agentName || ''} ${command || ''}`.toLowerCase();

  if (str.includes('hermes')) return 'hermes';
  if (str.includes('agy') || str.includes('antigravity')) return 'antigravity';
  if (str.includes('claude') || str.includes('anthropic')) return 'claude';
  if (str.includes('codex') || str.includes('openai') || str.includes('chatgpt') || str.includes('gpt')) return 'codex';
  if (str.includes('deepseek') || str.includes('deep-seek')) return 'deepseek';
  if (str.includes('kimi') || str.includes('kimmy') || str.includes('moonshot')) return 'kimi';
  if (str.includes('ollama')) return 'ollama';
  if (str.includes('gemini') || str.includes('google')) return 'gemini';
  if (str.includes('copilot') || str.includes('github')) return 'copilot';
  if (str.includes('cursor')) return 'cursor';
  if (str.includes('mistral') || str.includes('codestral') || str.includes('devin')) return 'mistral';
  if (str.includes('qwen') || str.includes('alibaba')) return 'qwen';
  if (str.includes('llama') || str.includes('meta')) return 'llama';

  return 'generic';
}

export function getProviderDisplayName(type: ProviderType): string {
  switch (type) {
    case 'hermes':
      return 'Hermes';
    case 'antigravity':
      return 'Antigravity';
    case 'claude':
      return 'Claude';
    case 'codex':
      return 'Codex / OpenAI';
    case 'deepseek':
      return 'DeepSeek';
    case 'kimi':
      return 'Kimi';
    case 'ollama':
      return 'Ollama';
    case 'gemini':
      return 'Gemini';
    case 'copilot':
      return 'GitHub Copilot';
    case 'cursor':
      return 'Cursor';
    case 'mistral':
      return 'Mistral';
    case 'qwen':
      return 'Qwen';
    case 'llama':
      return 'Llama';
    case 'none':
      return 'Terminal';
    case 'generic':
    default:
      return 'Agent Harness';
  }
}

